import React, { useState } from 'react';
import { saveFeedback } from '../idb';

function FeedbackForm() {
  const [rating, setRating] = useState('');
  const [comment, setComment] = useState('');

  const handleSubmit = async () => {
    const feedback = {
      rating,
      comment,
      timestamp: new Date().toISOString()
    };

    await saveFeedback(feedback);
    alert("Feedback saved locally!");

    if ('serviceWorker' in navigator && 'SyncManager' in window) {
      const registration = await navigator.serviceWorker.ready;
      await registration.sync.register('sync-feedback');
    }

    setRating('');
    setComment('');
  };

  return (
    <div>
      <h2>How was today’s food?</h2>
      <input placeholder="Rating (1–5)" value={rating} onChange={(e) => setRating(e.target.value)} />
      <textarea placeholder="Comments" value={comment} onChange={(e) => setComment(e.target.value)} />
      <button onClick={handleSubmit}>Submit</button>
    </div>
  );
}

export default FeedbackForm;
